  "connections": [
    {
      "event": "Q75207",
      "type": "took_part_in",
      "reason": "Marcus Aurelius ruled as the final emperor of the Pax Romana.",
      "evidence": "He was a member of the Nerva–Antonine dynasty, the last of the rulers later known as the Five Good Emperors and the last emperor of the Pax Romana, an age of relative peace, calm, and stability for the Roman Empire lasting from 27 BC to 180 AD.",
      "work": ""
    },
    {
      "event": "Q1192043",
      "type": "took_part_in",
      "reason": "During his reign alongside Lucius Verus, Rome fought a major conflict against the Parthian Empire.",
      "evidence": "In the East, the Romans fought the Parthian War of Lucius Verus with a revitalised Parthian Empire and the rebel Kingdom of Armenia.",
      "work": ""
    },
    {
      "event": "Q933963",
      "type": "took_part_in",
      "reason": "Marcus Aurelius personally fought and defeated invading Germanic and Sarmatian tribes during the Marcomannic Wars.",
      "evidence": "Marcus defeated the Marcomanni, Quadi, and Iazyges in the Marcomannic Wars.",
      "work": ""
    },
    {
      "event": "Q599141",
      "type": "lived_through",
      "reason": "The Antonine Plague occurred during his reign, severely devastating the empire and possibly killing his co-emperor.",
      "evidence": "The Antonine Plague broke out in 165 or 166 and devastated the population of the Roman Empire, causing the deaths of five to ten million people.",
      "work": ""
    }
  ]
}

